mapper.select:
select t.id, t.group_id, t.module_code, t.title, t.creator_id, t.create_time, t.update_time, u.nick_name as creator_name, g.group_name as group_name, (select count(*) from te_topic_reply r where r.topic_id = t.id) as reply_count from te_topic t left join sys_user u on u.user_id = t.creator_id left join te_group g on g.id = t.group_id
and t.group_id = #{groupId} and t.group_id in (select id from te_group where class_id = #{classId}) and t.module_code = #{moduleCode}
order by coalesce(t.update_time, t.create_time) desc
